CREATE OR REPLACE FUNCTION public.batch_changes_delete_changeset_refs()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE changesets SET batch_change_ids = batch_change_ids - OLD.id::text
    WHERE batch_change_ids ? OLD.id::text;
    RETURN NULL;
END;
$function$

